{"function": "() => {
    // Find element containing "Enrollment"
    const headers = Array.from(document.querySelectorAll('strong, span, div')).filter(el => el.textContent.includes('Enrollment'));
    let enrollmentValue = null;
    for (let header of headers) {
        // Look for sibling element that contains the number
        let parent = header.parentElement;
        if (parent) {
            // Look for a sibling that is a div or span with number
            let siblings = Array.from(parent.children);
            for (let sibling of siblings) {
                if (sibling.textContent.match(/^\d+$/)) {
                    enrollmentValue = sibling.textContent.trim();
                    break;
                }
            }
        }
    }
    // If not found, try looking for the actual enrollment value in the study overview section
    if (!enrollmentValue) {
        const overview = document.getElementById('study-overview');
        if (overview) {
            const texts = overview.innerText.split('\n');
            for (let line of texts) {
                if (line.includes('Enrollment')) {
                    const match = line.match(/Enrollment\s*\(Actual\)\s*(\d+)/);
                    if (match) {
                        enrollmentValue = match[1];
                        break;
                    }
                }
            }
        }
    }
    return enrollmentValue;
}"}

